verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const migs=fs.readdirSync("supabase/migrations").filter((f)=>f.endsWith(".sql")).sort().map((f)=>fs.readFileSync("supabase/migrations/"+f,"utf8").replace(/^\s*--.*$/gm," ")).join("\n")
if(!/create table if not exists public\.commerce_order_transfers/.test(migs))fail("no migration creates public.commerce_order_transfers, so the transfer each seller is owed is nowhere recorded")
const tail=migs.slice(migs.indexOf("create table if not exists public.commerce_order_transfers"))
if(!/planned/.test(tail)||!/failed/.test(tail))fail("the transfer row has no planned or failed state, so a transfer that did not land looks like one that did")
if(!/unique\s*\(\s*order_id\s*,\s*seller_key\s*\)/.test(tail))fail("nothing stops a second row for the same seller on the same order, so a replayed settle can plan a second payment")
const tr=rd("lib/commerce/transfers.ts")
if(tr===null||!/transfers\.create\(/.test(tr))fail("nothing creates a transfer, so a split order pays nobody")
if(!/idempotencyKey:\s*transferIdempotencyKey\(row\.id\)/.test(tr))fail("a transfer is not created under a key fixed to its ledger row, so a retry can pay a seller twice")
if(!/settleSplitOrderTransfers\(/.test(rd("lib/commerce/checkout.ts")||""))fail("the settle never hands a paid split order to the ledger, so the charge lands and nobody is paid")
if(rd("app/api/cron/reconcile-transfers/route.ts")===null||!/reconcile-transfers/.test(rd("vercel.json")||""))fail("no reconciler is scheduled, so a transfer that failed stays failed until a person notices")
if(!/transfer\.reversed/.test(rd("app/api/webhooks/stripe/route.ts")||""))fail("a reversal made outside the product is acked and forgotten, so the ledger says a seller holds money they no longer hold")
console.log("ok")'
